UPDATE wms_batch_location_balance SET reserved_quantity = reserved_quantity + #{quantity}
WHERE tenant_id = #{tenantId} AND warehouse_id = #{stock.warehouseId}
  AND batch_no = #{stock.batchNo} AND location_id = #{stock.locationId}
  AND quantity - reserved_quantity >= #{quantity}

UPDATE wms_batch_location_balance SET picked_quantity = picked_quantity + #{quantity}
WHERE tenant_id = #{tenantId} AND batch_no = #{a.batchNo} AND location_id = #{a.locationId}
  AND reserved_quantity - picked_quantity >= #{quantity}
